        if (x + y == 0) return 0;
        if (x + y == 2) return 2;
        if (x + y == 1) return 3;
        if (memo[x][y] != -1) return memo[x][y];
        return memo[x][y] = std::min(dfs(std::abs(x - 1), std::abs(y - 2)), dfs(std::abs(x - 2), std::abs(y - 1))) + 1;
