class Solution {
    int[][] memo = new int[305][305];

    int dfs(int x, int y) {
        if (x + y == 0) return 0;
        if (x + y == 2) return 2;
        if (x + y == 1) return 3;
        if (memo[x][y] != 0) return memo[x][y];
        return memo[x][y] = Math.min(dfs(Math.abs(x - 1), Math.abs(y - 2)), dfs(Math.abs(x - 2), Math.abs(y - 1))) + 1;
    }

    public int minKnightMoves(int x, int y) {
        return dfs(Math.abs(x), Math.abs(y));
