var minKnightMoves = function(x, y) {
    const memo = new Map();
    const dfs = (cx, cy) => {
        if (cx + cy === 0) return 0;
        if (cx + cy === 2) return 2;
        if (cx + cy === 1) return 3;
        const key = cx * 1000 + cy;
        if (memo.has(key)) return memo.get(key);
        const ans = Math.min(dfs(Math.abs(cx - 1), Math.abs(cy - 2)), dfs(Math.abs(cx - 2), Math.abs(cy - 1))) + 1;
        memo.set(key, ans);
        return ans;
    };
    return dfs(Math.abs(x), Math.abs(y));
};
